const CONTROL_PAYLOAD = true;
const EXPLOIT_PAYLOAD = false;

function sameDescriptor(left, right) {
  if (!left || !right) return false;
  const keys = Reflect.ownKeys(left);
  return keys.length === Reflect.ownKeys(right).length && keys.every((key) => Object.is(left[key], right[key]));
}

function sameDescriptors(left, right) {
  const keys = Reflect.ownKeys(left);
  return keys.length === Reflect.ownKeys(right).length && keys.every((key) => sameDescriptor(left[key], right[key]));
}

function run_target(ownsValue) {
  let reads = 0;
  const ownedPrototype = {};
  Object.defineProperty(ownedPrototype, 'ownedValue', {
    get() { reads += 1; return 'owned'; }, enumerable: false, configurable: true,
  });
  const before = Object.getOwnPropertyDescriptor(ownedPrototype, 'ownedValue');
  const sharedBefore = Object.getOwnPropertyDescriptors(Object.prototype);
  const instance = Object.create(ownedPrototype);
  if (ownsValue) Object.defineProperty(instance, 'ownedValue', { value: 'owned', enumerable: true, writable: true, configurable: true });
  const result = validate(instance, { type: 'object', properties: { ownedValue: { type: 'string' } } });
  if (!result.valid || result.errors.length !== 0) throw new Error('owned validation did not complete successfully');
  if (Object.getPrototypeOf(instance) !== ownedPrototype || !sameDescriptor(before, Object.getOwnPropertyDescriptor(ownedPrototype, 'ownedValue'))) throw new Error('owned object shape changed');
  if (!sameDescriptors(sharedBefore, Object.getOwnPropertyDescriptors(Object.prototype))) throw new Error('shared prototype shape changed');
  return reads === 0;
}

module.exports = { CONTROL_PAYLOAD, EXPLOIT_PAYLOAD, run_target };
